extractor:
function extract(raw, memory, info) {
  raw = raw || {}; memory = memory || {}; info = info || {};
  var TICK = 16, G = 0.25, JUMP = -4.6, OFF = 12, PAD = 2, BIG = 1e9, DEAD = -1e9;
  var H = 60, CG = 190, S_UP = 1, S_DN = 1.2, SOFT = 10, SOFTPAD = 20, DISC = 0.05, BUDGET = 20000, AIM = 16;
  var i, j, n;
  function isNum(a) { return typeof a === 'number' && isFinite(a); }
  function num(a, d) { return isNum(a) ? a : d; }
  // tilted bird: [half height of the rotated box (ground test), half height of the game's reduced hitbox (pipe test)]
  function boxOf(v) {
    var a = Math.abs(Math.min(v / 10 * 90, 90)) * Math.PI / 180;
    var bh = 34 * Math.sin(a) + 24 * Math.cos(a);
    return [bh / 2, (24 + bh) / 4];
  }
  var screen = num(raw.screen, -1);
  var ground = num(raw.ground, num(raw.height, 420));
  var bird = raw.bird || {};
  var cx = num(bird.x, 59) + num(bird.w, 36) / 2;
  var BL = cx - 17, BR = cx + 17;
  var top = num(raw.top, num(bird.y, 200));
  var v0 = num(raw.velocity, 0);
  var lag = Math.max(0, num(info.lagMs, 0));
  var now = isNum(info.nowMs) ? info.nowMs : (isNum(memory.lastNow) ? memory.lastNow + TICK : 0);

  // game frame length: whole gravity steps (+0.25 each) over flap-free intervals, counting intervals with no frame
  if (screen === 1 && memory.lastScreen === 1 && isNum(memory.lastV) && isNum(memory.lastNow) && now > memory.lastNow && now - memory.lastNow <= 400) {
    var frf = (v0 - memory.lastV) / G, fr = Math.round(frf);
    if (memory.lastV > -3.5 && v0 > -4 && fr >= 0 && Math.abs(frf - fr) < 0.2) {
      memory.fT = (memory.fT || 0) + now - memory.lastNow; memory.fN = (memory.fN || 0) + fr;
    }
  }
  var FRAME = memory.fN >= 30 ? Math.min(18, Math.max(15, memory.fT / memory.fN)) : 1000 / 60;

  var pipes = [], odd = [], list = Array.isArray(raw.pipes) ? raw.pipes : [];
  for (i = 0; i < list.length; i++) {
    var p = list[i];
    if (!p || !isNum(p.x)) continue;
    if (isNum(p.gapTop) && isNum(p.gapBottom)) pipes.push({ x: p.x, w: num(p.w, 52), gt: p.gapTop, gb: p.gapBottom });
    else odd.push({ kind: 'pipe', x: p.x, y: num(p.y, 0), w: num(p.w, 52), h: num(p.h, ground) });
  }
  var known = { screen: 1, bird: 1, top: 1, velocity: 1, ground: 1, width: 1, height: 1, pipes: 1 };
  for (var key in raw) {
    if (known[key] || /cloud|star|score|digit|decor|sky|back|text|label|title|medal|best/i.test(key)) continue;
    var val = raw[key], arr = Array.isArray(val) ? val : (val && typeof val === 'object' ? [val] : []);
    for (i = 0; i < arr.length && i < 20; i++) {
      var o = arr[i];
      if (o && typeof o === 'object' && isNum(o.x)) odd.push({ kind: key, x: o.x, y: num(o.y, 0), w: num(o.w, num(o.width, 0)), h: num(o.h, num(o.height, 0)) });
    }
  }
  var unk = null, unkN = 0;
  for (i = 0; i < odd.length; i++) {
    if (odd[i].x + odd[i].w < BL) continue;
    unkN++;
    if (!unk || odd[i].x < unk.x) unk = odd[i];
  }
  pipes.sort(function (a, b) { return a.x - b.x; });
  var ahead = [];
  for (i = 0; i < pipes.length; i++) if (pipes[i].x + pipes[i].w >= BL) ahead.push(pipes[i]);
  var lead = ahead[0], sec = ahead[1];

  // pipe speed (px/ms), measured on the leading pipe
  var speed = isNum(memory.speed) ? memory.speed : 1000 / 7500;
  if (screen === 1 && lead) {
    var tr = memory.track;
    if (tr && tr.gt === lead.gt && tr.gb === lead.gb && lead.x <= tr.x + 1 && now >= tr.t) {
      if (now - tr.t >= 200) { var sp = (tr.x - lead.x) / (now - tr.t); if (sp > 0.03 && sp < 0.6) speed = sp; }
    } else memory.track = { gt: lead.gt, gb: lead.gb, x: lead.x, t: now };
  } else if (screen !== 1) memory.track = null;
  memory.speed = speed;

  var passed = memory.passed || 0;
  if (screen === 1 && lead && isNum(memory.leadX) && lead.x > memory.leadX + 60) passed++;
  memory.passed = passed;
  memory.leadX = lead ? lead.x : null;

  // lookahead: memoised search over flap times (every frame for 10 frames, then every 2, then every 3), max-min clearance
  var hT = [], hB = [], sT = [], sB = [], tg = [], FA = [], EA = [], FB = [], EB = [];
  var memo = {}, steps = 0;
  function clr(j, cy, e, fh) {
    var c = ground - cy - fh;
    if (c <= 0) return DEAD;
    var bt = cy - e, bb = cy + e, x;
    if (hT[j] > -BIG) {
      x = bt - hT[j]; if (x <= 0) return DEAD; if (x < c) c = x;
      x = hB[j] - bb; if (x <= 0) return DEAD; if (x < c) c = x;
    }
    x = Math.min(bt - sT[j], sB[j] - bb) + SOFTPAD;
    if (x < c) c = x;
    c += DISC * j;
    return c > CG ? CG : (c < -150 ? -150 : c);
  }
  function canFlap(j) { return j < H && (j <= 10 || (j <= 30 ? j % 2 === 0 : j % 3 === 0)); }
  function run(f, y, flap) {
    var E = flap ? EB : EA, Fh = flap ? FB : FA, base = flap ? JUMP : v0;
    var cj = [], cy = [], cm = [], cs = [], m = BIG, dead = 0, yy = y, jj, nn, vv, c, a, b;
    for (jj = f + 1; jj <= H; jj++) {
      nn = flap ? jj - f : jj; vv = base + G * nn; yy += vv; steps++;
      c = clr(jj, yy + OFF, E[nn], Fh[nn]);
      if (c === DEAD) { dead = jj; break; }
      if (c < m) m = c;
      if (yy + OFF - E[nn] <= 0) yy = 0;
      if (canFlap(jj)) { cj.push(jj); cy.push(yy); cm.push(m); cs.push(Math.abs(yy + OFF - tg[jj + 1] - AIM) + (vv < 0 ? 60 : 0)); }
    }
    var best = dead ? dead - 300 : (m >= BIG ? CG : m), ord = [];
    for (a = 0; a < cj.length; a++) ord.push(a);
    ord.sort(function (p1, p2) { return cs[p1] - cs[p2]; });
    for (b = 0; b < ord.length && best < CG && steps <= BUDGET; b++) {
      a = ord[b];
      if (cm[a] <= best) continue;
      c = V(cj[a], cy[a]);
      if (c > cm[a]) c = cm[a];
      if (c > best) best = c;
    }
    return best;
  }
  function V(f, y) {
    var k = f * 4096 + Math.round(y) + 1024, r = memo[k];
    if (r === undefined) { r = run(f, y, true); memo[k] = r; }
    return r;
  }

  var mF = 0, mW = 0;
  if (screen === 1) {
    try {
      var nA = Math.min(ahead.length, 4);
      for (j = 0; j <= H; j++) {
        var t = (j - 0.5) * FRAME, ht = -BIG, hb = BIG, st = -BIG, sb = BIG, first = true;
        for (i = 0; i < nA; i++) {
          var q = ahead[i], xj = q.x - speed * t;
          if (xj + q.w - PAD < BL) continue;
          if (first) { first = false; if (xj - PAD < BR) { ht = q.gt; hb = q.gb; continue; } }
          var d = Math.max(0, xj - PAD - BR);
          st = Math.max(st, q.gt - S_UP * d - SOFT);
          sb = Math.min(sb, q.gb + S_DN * d + SOFT);
        }
        hT.push(ht); hB.push(hb); sT.push(st); sB.push(sb);
        tg.push(ht > -BIG ? (ht + hb) / 2 : (st > -BIG ? (Math.max(st, 40) + Math.min(sb, ground - 40)) / 2 : ground - 200));
      }
      for (n = 0; n <= H + 1; n++) {
        var ba = boxOf(v0 + G * n), bf = boxOf(JUMP + G * n);
        FA.push(ba[0]); EA.push(ba[1]); FB.push(bf[0]); EB.push(bf[1]);
      }
      var L = lag > 0 ? Math.min(20, Math.round(lag / FRAME)) : 0, yL = top, mPre = BIG, deadPre = 0;
      for (n = 1; n <= L; n++) {
        yL += v0 + G * n;
        var cp = clr(n, yL + OFF, EA[n], FA[n]);
        if (cp === DEAD) { deadPre = n; break; }
        if (cp < mPre) mPre = cp;
        if (yL + OFF - EA[n] <= 0) yL = 0;
      }
      if (deadPre) { mF = deadPre - 300; mW = mF; }
      else {
        steps = 0; mF = Math.min(mPre, V(L, yL));
        steps = 0; mW = Math.min(mPre, run(L, yL, false));
      }
    } catch (err) { mF = 0; mW = 0; }
  }

  var b0 = boxOf(v0), cy0 = top + OFF, bt0 = cy0 - b0[1], bb0 = cy0 + b0[1], diff = mF - mW;
  memory.lastNow = now; memory.lastV = v0; memory.lastScreen = screen;
  return {
    over: screen === 2,
    playing: screen === 1,
    birdY: Math.round(cy0),
    vel: Math.round(v0 * 10) / 10,
    roomToGround: Math.round(ground - cy0 - b0[0]),
    pipeDx: lead ? Math.round(lead.x - BR) : null,
    inPipe: lead ? lead.x - PAD < BR : false,
    roomAbove: lead ? Math.round(bt0 - lead.gt) : null,
    roomBelow: lead ? Math.round(lead.gb - bb0) : null,
    msToPipe: lead ? Math.round(Math.max(0, lead.x - PAD - BR) / speed) : null,
    msToClear: lead ? Math.round(Math.max(0, lead.x + lead.w - PAD - BL) / speed) : null,
    nextGapShift: lead && sec ? Math.round((sec.gt + sec.gb - lead.gt - lead.gb) / 2) : null,
    marginIfFlap: Math.round(mF),
    marginIfWait: Math.round(mW),
    flapEffect: screen !== 1 ? 'same' : (diff > 0.1 ? 'moreRoom' : (diff < -0.1 ? 'lessRoom' : 'same')),
    crashIfFlap: screen === 1 && mF < -200,
    crashIfWait: screen === 1 && mW < -200,
    passed: passed,
    unknownThing: unk ? { kind: String(unk.kind).slice(0, 16), dx: Math.round(unk.x - BR), y: Math.round(unk.y), w: Math.round(unk.w), h: Math.round(unk.h), count: unkN } : null
  };
}

teacher:
function teach(state) {
  if (!state || state.over) return 'wait';
  if (!state.playing) return 'flap';
  return state.flapEffect === 'moreRoom' ? 'flap' : 'wait';
}
